let isFirstLoad=!sessionStorage.getItem('hasVisited');document.addEventListener('DOMContentLoaded',()=>{document.body.style.opacity='0';setTimeout(()=>{document.body.style.opacity='1';},50);if(isFirstLoad){sessionStorage.setItem('hasVisited','true');}});document.addEventListener('click',(e)=>{const link=e.target.closest('a');if(!link||link.target==='_blank'||link.hostname!==window.location.hostname){return;}if(link.hasAttribute('download')||link.href.startsWith('mailto:')||link.href.startsWith('tel:')){return;}const href=link.href;if(href===window.location.href){e.preventDefault();return;}e.preventDefault();document.body.style.opacity='0';setTimeout(()=>{window.location.href=href;},400);});window.addEventListener('pageshow',(event)=>{if(event.persisted){document.body.classList.remove('fade-out','content-fade-out');document.body.style.opacity='1';}});